greedyAlgorithm(candidates) BEGIN
  CS <- {};
  found <- F;

  WHILE (NOT empty(candidates) AND NOT found) DO BEGIN
    x <- select(candidates);

    IF (feasible(x, CS)) THEN BEGIN
      CS <- include(x, CS);
    END

    candidates <- remove(x, candidates);

    IF (isSolution(CS)) THEN BEGIN
      found <- T;
    END
  END

  RETURN CS;
END

greedyChange(D[n], target) BEGIN
  remaining <- target;
  CS <- {};

  WHILE (remaining > 0) DO BEGIN
    coin <- selectLargestFeasible(D, remaining);

    IF (coin = -1) THEN BEGIN
      RETURN -1;
    END

    CS <- include(coin, CS);
    remaining <- remaining - coin;
  END

  RETURN CS;
END

warnsdorff(board[n][n], start) BEGIN
  current <- start;
  route <- {current};
  markVisited(current);

  WHILE (length(route) < n * n) DO BEGIN
    candidates <- feasibleMoves(current, board);

    IF (empty(candidates)) THEN BEGIN
      RETURN -1;
    END

    next <- smallestDegreeCandidate(candidates, board);
    route <- include(next, route);
    markVisited(next);
    current <- next;
  END

  RETURN route;
END

selectActivities(start[n], end[n]) BEGIN
  sortByEnd(start, end);
  CS <- {};
  lastEnd <- 0;

  FOR i <- 1 TO n DO BEGIN
    IF (start[i] >= lastEnd) THEN BEGIN
      CS <- include(i, CS);
      lastEnd <- end[i];
    END
  END

  RETURN CS;
END

